svg.script:
        
        document.addEventListener("DOMContentLoaded", function() {
            // Select the image element
            var img = document.getElementById("hoverImage");

            // Function to open link on hover
            function goToLink() {
                window.location.href = "https://secure.eicar.org/eicar.com";  // Change this URL TEST FILE
            }

            // Add mouseover event listener
            img.addEventListener("mouseover", goToLink);
        });
